    "             Pe[0].z == 2.0 ? textureGrad(samp_multilayerextramap1, uv * bt, dx * bt, dy * bt) : vec4(0.5, 0.5, 0.0, 0.0);\n"
    "    float g = Pe[0].w == 1.0 ? textureGrad(samp_multilayerextramap0, uv, dx, dy).y :\n"
    "              Pe[0].w == 2.0 ? textureGrad(samp_multilayerextramap1, uv, dx, dy).y : 1.0;\n"
    "    float ig = 1.0 - g;\n"
    "    float bb = B.z;\n"
    "    float w = clamp(1.0 - g * g, 0.0, 1.0);\n"
    "    float w2 = w * w;\n"
    "    float w3 = w2 * w;\n"
    "    float m = clamp(w3 * bb * (2.0 - w) - (1.0 - w3) + clamp(8.0 * w2 - 7.0, 0.0, 1.0), 0.0, 1.0);\n"
    "    m = clamp(16.0 * m, 0.0, 1.0);\n"
    "    float m2 = m * m;\n"
    "    f_spec.xyz = f_spec.xyz + (vec3(0.02) - f_spec.xyz) * m2;\n"
    "    f_smooth = f_smooth + (0.75 - f_smooth) * m2;\n"
    "    vec2 N = (r.xy + 1.0) * 0.5;\n"
    "    vec2 nxy = N + (B.xy - N) * ig;\n"
    "    vec3 charcoal = vec3(0.01) + (vec3(0.12, 0.11, 0.10) - vec3(0.01)) * bb;\n"
    "    f_alb.xyz = f_alb.xyz + (charcoal - f_alb.xyz) * ig;\n"
    "    f_smooth = f_smooth + ((0.1 + (0.7 - 0.1) * bb) - f_smooth) * ig;\n"
    "    f_spec.xyz = f_spec.xyz + (vec3(0.048) - f_spec.xyz) * ig;\n"
    "    vec3 hot = (bb * bb) * Pe[3].xyz;\n"
    "    vec3 e1 = hot + (f_em.xyz - hot) * g;\n"
    "    float s = (B.w + (bb - B.w) * ig) * ig;\n"
    "    vec3 k = (vec3(s) + (e1 - vec3(s)) * g) * vec3(1.0, 0.07, 0.0) * 25.0 * (nxy.x * nxy.y);\n"
    "    vec4 nt = Pe[2];\n"
    "    vec2 u1 = vec2(uv.x * nt.x, uv.y * nt.x + time * nt.z);\n"
    "    vec2 u2 = vec2(uv.x * nt.y, uv.y * nt.y - time * nt.w);\n"
    "    float n1 = textureGrad(samp_magnificationclouds, u1, dx * nt.x, dy * nt.x).x;\n"
    "    float n2 = textureGrad(samp_magnificationclouds, u2, dx * nt.y, dy * nt.y).x;\n"
    "    float fl = clamp(n1 * n1 * n2 * n2 + 0.12, 0.0, 1.0);\n"
    "    f_em.xyz = e1 + k * fl;\n"
    "    vec2 x = nxy * 2.0 - 1.0;\n"
    "    r = vec3(x, sqrt(clamp(1.0 - x.x * x.x - x.y * x.y, 0.0, 1.0)));\n"
    "}\n"
    "\n"
    "// P: the material's multilayer parameters, in the order the program declares them (renderparm names):\n"
    "//   0 layerstilingfactor  1 multiblendlayerscale  2 multiblendheightmapscale  3 multiblendsoftness\n"
    "//   4 multiblendalbedoscale  5 multiblendnormalscale  6 multiblendspecularscale  7 multiblendsmoothnessscale\n"
    "//   8 multiblendemissivescale  9 blendheightmapscale (x)  10 blendlayer0tiling  11 blendlayer0emissive (rgb: layer\n"
    "//   0's emissive colour, brightest channel 1)  12..15 blendlayer1..4tiling (surface tiling xy, scroll xy)\n"
    "//   16..19 blendlayer1..4specular (rgb: the layer's specular when it is one colour; w: 0 that colour, 1 or 2 the\n"
    "//   image in extra map 0 or 1)  20..23 blendlayer1..4emissive (rgb: the layer's emissive, relative to the board's\n"
    "//   emissive scale, or the factor of its emissive image; w: 0 that colour, 1 or 2 the image in extra map 0 or 1)\n"
    "//   24 multilayerember (x: 1 for an isember material; y: layer 0's emissive image in extra map 0 or 1, else the\n"
    "//   pages' mask (11's w then scales 11's rgb to the image's emissive on the board's scale); z: the burnt tile in extra map 0 or 1, else none; w: the\n"
    "//   wound cap's blood image in extra map 0 or 1, else none)  25 multilayerembertiling (xy: the burnt tile's tiling)\n"
    "//   26 multilayerembernoise (Eternal's emissivenoisetiling)  27 multilayeremberhot (rgb: the ember colour on the\n"
    "//   board's emissive scale)\n"
    "// E: bloommaskscale, colorscale, color, bloomcolor (the program's emissive factors)\n"
    "void ml_blend(inout vec3 albedo, inout vec3 specular, inout float smoothness, inout vec3 normal,\n"
    "              inout vec3 lightmap, inout vec3 emissive, inout float thickness, vec4 texcoords, float time, vec4 P[28],\n"
    "              vec4 E[4])\n"
    "{\n"
    "    vec2 uv = texcoords.xy;\n"
    "    vec2 dx = dFdx(uv);\n"
    "    vec2 dy = dFdy(uv);\n"
    "\n"
    "    // layer 0, read back from the inputs the pages gave\n"
    "    vec4 f_alb = vec4(albedo, 1.0);\n"
    "    vec4 f_spec = vec4(specular, 1.0);\n"
    "    float f_smooth = ml_srgb_enc(smoothness);\n"
    "    vec2 base_n = normal.xy;\n"
    "    vec4 f_n = vec4(0.5, 0.5, 0.0, 0.0);\n"
    "    // the pages' mask is read from the sRGB plane already decoded; its square is layer 0's emissive intensity (the\n"
    "    // converter writes the sRGB encoding of its square root)\n"
    "    float raw0 = lightmap.x;\n"
    "    vec4 f_em = vec4(P[11].xyz * (raw0 * raw0), 0.0);\n"
    "\n"
    "    vec2 uv0 = uv * P[10].xy + time * P[10].zw;\n"
    "    if (P[24].y != 0.0) {\n"
    "        // an ember material reads layer 0's emissive image itself (its colour, not only the pages' mask)\n"
    "        vec2 d0x = dx * P[10].xy, d0y = dy * P[10].xy;\n"
    "        vec3 e0 = P[24].y == 1.0 ? textureGrad(samp_multilayerextramap0, uv0, d0x, d0y).xyz : textureGrad(samp_multilayerextramap1, uv0, d0x, d0y).xyz;\n"
    "        f_em = vec4(e0 * P[11].xyz * P[11].w, 0.0);\n"
    "    }\n"
    "    float h0 = textureGrad(samp_blendlayer0heightmap, uv0, dx * P[10].xy, dy * P[10].xy).x;\n"
    "    vec4 M = min(textureGrad(samp_layerblendmask, uv, dx, dy) * P[1], vec4(1.0));\n"
    "    float hb = (h0 - ML_HEIGHT_MID) * P[9].x;\n"
    "\n"
    "    ml_layer(0, M[0], hb, uv, dx, dy, time, P, samp_blendlayer1albedomap, samp_blendlayer1normalmap, samp_blendlayer1smoothnessmap, samp_blendlayer1heightmap,\n"
    "             f_alb, f_spec, f_smooth, f_n, f_em);\n"
    "    ml_layer(1, M[1], hb, uv, dx, dy, time, P, samp_blendlayer2albedomap, samp_blendlayer2normalmap, samp_blendlayer2smoothnessmap, samp_blendlayer2heightmap,\n"
    "             f_alb, f_spec, f_smooth, f_n, f_em);\n"
    "    ml_layer(2, M[2], hb, uv, dx, dy, time, P, samp_blendlayer3albedomap, samp_blendlayer3normalmap, samp_blendlayer3smoothnessmap, samp_blendlayer3heightmap,\n"
    "             f_alb, f_spec, f_smooth, f_n, f_em);\n"
    "    ml_layer(3, M[3], hb, uv, dx, dy, time, P, samp_blendlayer4albedomap, samp_blendlayer4normalmap, samp_blendlayer4smoothnessmap, samp_blendlayer4heightmap,\n"
    "             f_alb, f_spec, f_smooth, f_n, f_em);\n"
    "\n"
    "    // reoriented normal mapping onto layer 0's normal\n"
    "    vec3 n0 = ml_decode_normal(base_n);\n"
    "    vec3 d = ml_decode_normal(f_n.xy);\n"
    "    vec3 tt = n0 + vec3(0.0, 0.0, 1.0);\n"
    "    vec3 uu = vec3(-d.x, -d.y, d.z);\n"
    "    vec3 r = normalize(tt * dot(tt, uu) - uu * tt.z);\n"
    "    if (P[24].x != 0.0) {\n"
    "        vec4 Pe[4] = vec4[4](P[24], P[25], P[26], P[27]);\n"
    "        ml_ember(uv, dx, dy, time, Pe, f_alb, f_spec, f_smooth, r, f_em);\n"
    "    }\n"
    "\n"
    "    albedo = f_alb.xyz;\n"
    "    vec3 se = ml_srgb_enc3(f_spec.xyz);\n"
    "    float grey = dot(se, vec3(0.2126, 0.7152, 0.0722));\n"
    "    specular = vec3(ml_srgb_dec(grey));\n"
    "    smoothness = ml_srgb_dec(clamp(f_smooth, 0.0, 1.0));\n"
    "    normal.xy = clamp((r.xy * 128.0 + 128.0) / 255.0, 0.0, 1.0);\n"
    "    float em = max(f_em.x, max(f_em.y, f_em.z));\n"
    "    vec3 ka = E[1].x * E[2].xyz * f_alb.xyz;\n"
    "    float kj = E[3].x >= max(E[3].y, E[3].z) ? ka.x : (E[3].y >= E[3].z ? ka.y : ka.z);\n"
    "    em = em / (1.0 + max(kj, 0.0));\n"
    "    float lmx = sqrt(clamp(em, 0.0, 1.0));\n"
    "    lightmap.x = lmx;\n"
    "    emissive = vec3(E[0].x * lmx * lmx * E[1].x) * E[2].xyz * E[3].xyz;\n"
    "    thickness = lightmap.y;\n"
    "}\n"
;

const char SH_MODPROG_ML_DECL[] =
    "\t\t// multilayer.decl.inc -- the multilayer blend of the product's render programs (modprog.h) in the render\n"
    "\t\t// program language, for the OpenGL renderer, which compiles a program from its decl text. modprog.c inserts this\n"
    "\t\t// text before the base program's CUSTOM_TEXTURE_INPUTS template and MULTILAYER_BLEND( inputs ) as that template's\n"
    "\t\t// first statement. The same function, line for line, as ml_blend in multilayer.frag (the Vulkan module): see there\n"
    "\t\t// for DOOM Eternal's rule and what each input becomes. The engine compiles a program's fragment text inside\n"
    "\t\t// main(), so the helpers are macros and templates, never functions.\n"
    "\t\t#define mlSrgbEncode( v ) ( saturate( v ) <= 0.0031308 ? saturate( v ) * 12.92 : 1.055 * pow( saturate( v ), 1.0 / 2.4 ) - 0.055 )\n"
    "\t\t#define mlSrgbDecode( v ) ( ( v ) <= 0.04045 ? ( v ) / 12.92 : pow( ( ( v ) + 0.055 ) / 1.055, 2.4 ) )\n"
    "\t\t#template ML_DECODE_NORMAL( dst, v ) {\n"
    "\t\t\tfloat2 mlDn = ( v ) * ( 255.0 / 128.0 ) - 1.0;\n"
    "\t\t\tdst = float3( mlDn.x, mlDn.y, sqrt( saturate( 1.0 - mlDn.x * mlDn.x - mlDn.y * mlDn.y ) ) );\n"
    "\t\t}\n"
    "\t\t#endtemplate\n"
    "\n"
    "\t\t#template MULTILAYER_LAYER( L, albedoMap, normalMap, smoothnessMap, heightMap, layerTiling, layerSpecular, layerEmissive ) {\n"
    "\t\t\tfloat m = mlMask.L;\n"
    "\t\t\tBRANCH if ( m != 0.0 ) {\n"
    "\t\t\t\tfloat tl = $snapmapplusvec0.L;\n"
    "\t\t\t\tfloat hi = ( tex2D( heightMap, mlUv * tl, mlDx * tl, mlDy * tl ).x - 0.49803921580314636 ) * $snapmapplusvec2.L;\n"
    "\t\t\t\tfloat a = ( mlHb + 1.0 ) - m;\n"
    "\t\t\t\tfloat b = ( hi + 0.0 ) + m;\n"
    "\t\t\t\tfloat t0 = clamp( ( b - a ) / $snapmapplusvec3.L, -1.0, 1.0 ) / 2.0 + 0.5;\n"
    "\t\t\t\tfloat f = saturate( ( abs( 0.5 - m ) - ( 0.5 - 0.1 ) ) / 0.1 );\n"
    "\t\t\t\tfloat t = t0;\n"
    "\t\t\t\tif ( m < 0.1 && t0 > m ) {\n"
    "\t\t\t\t\tt = lerp( t0, m, f );\n"
    "\t\t\t\t} else if ( m > 1.0 - 0.1 && t0 < m ) {\n"
    "\t\t\t\t\tt = lerp( t0, m, f );\n"
    "\t\t\t\t}\n"
    "\t\t\t\tfloat2 lsc = layerTiling.xy;\n"
    "\t\t\t\tfloat2 lu = ( mlUv * tl ) * lsc + _float2( mlTime ) * layerTiling.zw;\n"
    "\t\t\t\tfloat2 ldx = mlDx * tl * lsc;\n"
    "\t\t\t\tfloat2 ldy = mlDy * tl * lsc;\n"
    "\t\t\t\tBRANCH if ( $snapmapplusvec4.L != 0.0 ) {\n"
    "\t\t\t\t\tmlAlbedo = lerp( mlAlbedo, float4( tex2D( albedoMap, lu, ldx, ldy ).xyz, 1.0 ), _float4( t * $snapmapplusvec4.L ) );\n"
    "\t\t\t\t}\n"
    "\t\t\t\tBRANCH if ( $snapmapplusvec6.L != 0.0 ) {\n"
    "\t\t\t\t\tfloat3 ls = layerSpecular.w == 1.0 ? tex2D( $multilayerExtraMap0, lu, ldx, ldy ).xyz :\n"
    "\t\t\t\t\t\t( layerSpecular.w == 2.0 ? tex2D( $multilayerExtraMap1, lu, ldx, ldy ).xyz : layerSpecular.xyz );\n"
    "\t\t\t\t\tmlSpecular = lerp( mlSpecular, float4( ls, 1.0 ), _float4( t * $snapmapplusvec6.L ) );\n"
    "\t\t\t\t}\n"
    "\t\t\t\tBRANCH if ( $snapmapplusvec7.L != 0.0 ) {\n"
    "\t\t\t\t\tmlSmooth = lerp( mlSmooth, tex2D( smoothnessMap, lu, ldx, ldy ).x, t * $snapmapplusvec7.L );\n"
    "\t\t\t\t}\n"
    "\t\t\t\tBRANCH if ( $snapmapplusvec5.L != 0.0 ) {\n"
    "\t\t\t\t\tmlNormal = lerp( mlNormal, float4( tex2D( normalMap, lu, ldx, ldy ).xy, 0.0, 0.0 ), _float4( t * $snapmapplusvec5.L ) );\n"
    "\t\t\t\t}\n"
    "\t\t\t\tBRANCH if ( $snapmapplusvec8.L != 0.0 ) {\n"
    "\t\t\t\t\tfloat3 le = layerEmissive.w == 1.0 ? tex2D( $multilayerExtraMap0, lu, ldx, ldy ).xyz * layerEmissive.xyz :\n"
    "\t\t\t\t\t\t( layerEmissive.w == 2.0 ? tex2D( $multilayerExtraMap1, lu, ldx, ldy ).xyz * layerEmissive.xyz : layerEmissive.xyz );\n"
    "\t\t\t\t\tmlEmissive = lerp( mlEmissive, float4( le, 0.0 ), _float4( t * $snapmapplusvec8.L ) );\n"
    "\t\t\t\t}\n"
    "\t\t\t}\n"
    "\t\t}\n"
    "\t\t#endtemplate\n"
    "\n"
    "\t\t#template MULTILAYER_EMBER( mlR ) {\n"
    "\t\t\tfloat2 mlBt = $snapmapplusvec25.xy;\n"
    "\t\t\tfloat4 mlB = $snapmapplusvec24.z == 1.0 ? tex2D( $multilayerExtraMap0, mlUv * mlBt, mlDx * mlBt, mlDy * mlBt ) :\n"
    "\t\t\t\t( $snapmapplusvec24.z == 2.0 ? tex2D( $multilayerExtraMap1, mlUv * mlBt, mlDx * mlBt, mlDy * mlBt ) : float4( 0.5, 0.5, 0.0, 0.0 ) );\n"
    "\t\t\tfloat mlG = $snapmapplusvec24.w == 1.0 ? tex2D( $multilayerExtraMap0, mlUv, mlDx, mlDy ).y :\n"
    "\t\t\t\t( $snapmapplusvec24.w == 2.0 ? tex2D( $multilayerExtraMap1, mlUv, mlDx, mlDy ).y : 1.0 );\n"
    "\t\t\tfloat mlIg = 1.0 - mlG;\n"
    "\t\t\tfloat mlBb = mlB.z;\n"
    "\t\t\tfloat mlW = saturate( 1.0 - mlG * mlG );\n"
    "\t\t\tfloat mlW2 = mlW * mlW;\n"
    "\t\t\tfloat mlW3 = mlW2 * mlW;\n"
    "\t\t\tfloat mlM = saturate( mlW3 * mlBb * ( 2.0 - mlW ) - ( 1.0 - mlW3 ) + saturate( 8.0 * mlW2 - 7.0 ) );\n"
    "\t\t\tmlM = saturate( 16.0 * mlM );\n"
    "\t\t\tfloat mlM2 = mlM * mlM;\n"
    "\t\t\tmlSpecular.xyz = mlSpecular.xyz + ( _float3( 0.02 ) - mlSpecular.xyz ) * mlM2;\n"
    "\t\t\tmlSmooth = mlSmooth + ( 0.75 - mlSmooth ) * mlM2;\n"
    "\t\t\tfloat2 mlEn = ( mlR.xy + 1.0 ) * 0.5;\n"
    "\t\t\tfloat2 mlNxy = mlEn + ( mlB.xy - mlEn ) * mlIg;\n"
    "\t\t\tfloat3 mlChar = _float3( 0.01 ) + ( float3( 0.12, 0.11, 0.10 ) - _float3( 0.01 ) ) * mlBb;\n"
    "\t\t\tmlAlbedo.xyz = mlAlbedo.xyz + ( mlChar - mlAlbedo.xyz ) * mlIg;\n"
    "\t\t\tmlSmooth = mlSmooth + ( ( 0.1 + ( 0.7 - 0.1 ) * mlBb ) - mlSmooth ) * mlIg;\n"
    "\t\t\tmlSpecular.xyz = mlSpecular.xyz + ( _float3( 0.048 ) - mlSpecular.xyz ) * mlIg;\n"
    "\t\t\tfloat3 mlHot = ( mlBb * mlBb ) * $snapmapplusvec27.xyz;\n"
    "\t\t\tfloat3 mlE1 = mlHot + ( mlEmissive.xyz - mlHot ) * mlG;\n"
    "\t\t\tfloat mlS = ( mlB.w + ( mlBb - mlB.w ) * mlIg ) * mlIg;\n"
    "\t\t\tfloat3 mlK = ( _float3( mlS ) + ( mlE1 - _float3( mlS ) ) * mlG ) * float3( 1.0, 0.07, 0.0 ) * 25.0 * ( mlNxy.x * mlNxy.y );\n"
    "\t\t\tfloat4 mlNt = $snapmapplusvec26;\n"
    "\t\t\tfloat2 mlU1 = float2( mlUv.x * mlNt.x, mlUv.y * mlNt.x + mlTime * mlNt.z );\n"
    "\t\t\tfloat2 mlU2 = float2( mlUv.x * mlNt.y, mlUv.y * mlNt.y - mlTime * mlNt.w );\n"
    "\t\t\tfloat mlN1 = tex2D( $magnificationClouds, mlU1, mlDx * mlNt.x, mlDy * mlNt.x ).x;\n"
    "\t\t\tfloat mlN2 = tex2D( $magnificationClouds, mlU2, mlDx * mlNt.y, mlDy * mlNt.y ).x;\n"
    "\t\t\tfloat mlFl = saturate( mlN1 * mlN1 * mlN2 * mlN2 + 0.12 );\n"
    "\t\t\tmlEmissive.xyz = mlE1 + mlK * mlFl;\n"
    "\t\t\tfloat2 mlX = mlNxy * 2.0 - 1.0;\n"
    "\t\t\tmlR = float3( mlX.x, mlX.y, sqrt( saturate( 1.0 - mlX.x * mlX.x - mlX.y * mlX.y ) ) );\n"
    "\t\t}\n"
    "\t\t#endtemplate\n"
    "\n"
    "\t\t#template MULTILAYER_BLEND( inputs ) {\n"
    "\t\t\tfloat2 mlUv = inputs.texCoords.xy;\n"
    "\t\t\tfloat2 mlDx = ddx( mlUv );\n"
    "\t\t\tfloat2 mlDy = ddy( mlUv );\n"
    "\t\t\tfloat mlTime = $time.x;\n"
    "\t\t\tfloat4 mlAlbedo = float4( inputs.albedo.xyz, 1.0 );\n"
    "\t\t\tfloat4 mlSpecular = float4( inputs.specular.xyz, 1.0 );\n"
    "\t\t\tfloat mlSmooth = mlSrgbEncode( inputs.smoothness );\n"
    "\t\t\tfloat2 mlBaseNormal = inputs.normal.xy;\n"
    "\t\t\tfloat4 mlNormal = float4( 0.5, 0.5, 0.0, 0.0 );\n"
    "\t\t\tfloat mlRaw0 = inputs.lightmap.x;\t// decoded from the sRGB plane: its square is layer 0's intensity\n"
    "\t\t\tfloat4 mlEmissive = float4( $snapmapplusvec11.xyz * ( mlRaw0 * mlRaw0 ), 0.0 );\n"
    "\t\t\tfloat2 mlUv0 = mlUv * $snapmapplusvec10.xy + _float2( mlTime ) * $snapmapplusvec10.zw;\n"
    "\t\t\tBRANCH if ( $snapmapplusvec24.y != 0.0 ) {\n"
    "\t\t\t\tfloat2 mlD0x = mlDx * $snapmapplusvec10.xy;\n"
    "\t\t\t\tfloat2 mlD0y = mlDy * $snapmapplusvec10.xy;\n"
    "\t\t\t\tfloat3 mlE0 = $snapmapplusvec24.y == 1.0 ? tex2D( $multilayerExtraMap0, mlUv0, mlD0x, mlD0y ).xyz : tex2D( $multilayerExtraMap1, mlUv0, mlD0x, mlD0y ).xyz;\n"
    "\t\t\t\tmlEmissive = float4( mlE0 * $snapmapplusvec11.xyz * $snapmapplusvec11.w, 0.0 );\n"
    "\t\t\t}\n"
    "\t\t\tfloat mlH0 = tex2D( $blendLayer0HeightMap, mlUv0, mlDx * $snapmapplusvec10.xy, mlDy * $snapmapplusvec10.xy ).x;\n"
    "\t\t\tfloat4 mlMask = min( tex2D( $layerBlendMask, mlUv, mlDx, mlDy ) * $snapmapplusvec1, _float4( 1.0 ) );\n"
    "\t\t\tfloat mlHb = ( mlH0 - 0.49803921580314636 ) * $snapmapplusvec9.x;\n"
    "\t\t\tMULTILAYER_LAYER( x, $blendLayer1AlbedoMap, $blendLayer1NormalMap, $blendLayer1SmoothnessMap, $blendLayer1HeightMap, $snapmapplusvec12, $snapmapplusvec16, $snapmapplusvec20 );\n"
    "\t\t\tMULTILAYER_LAYER( y, $blendLayer2AlbedoMap, $blendLayer2NormalMap, $blendLayer2SmoothnessMap, $blendLayer2HeightMap, $snapmapplusvec13, $snapmapplusvec17, $snapmapplusvec21 );\n"
    "\t\t\tMULTILAYER_LAYER( z, $blendLayer3AlbedoMap, $blendLayer3NormalMap, $blendLayer3SmoothnessMap, $blendLayer3HeightMap, $snapmapplusvec14, $snapmapplusvec18, $snapmapplusvec22 );\n"
    "\t\t\tMULTILAYER_LAYER( w, $blendLayer4AlbedoMap, $blendLayer4NormalMap, $blendLayer4SmoothnessMap, $blendLayer4HeightMap, $snapmapplusvec15, $snapmapplusvec19, $snapmapplusvec23 );\n"
    "\t\t\t// reoriented normal mapping onto layer 0's normal\n"
    "\t\t\tfloat3 mlN0;\n"
    "\t\t\tML_DECODE_NORMAL( mlN0, mlBaseNormal );\n"
    "\t\t\tfloat3 mlD;\n"
    "\t\t\tML_DECODE_NORMAL( mlD, mlNormal.xy );\n"
    "\t\t\tfloat3 mlT = mlN0 + float3( 0.0, 0.0, 1.0 );\n"
    "\t\t\tfloat3 mlU = float3( -mlD.x, -mlD.y, mlD.z );\n"
    "\t\t\tfloat3 mlR = normalize( mlT * dot( mlT, mlU ) - mlU * mlT.z );\n"
    "\t\t\tBRANCH if ( $snapmapplusvec24.x != 0.0 ) {\n"
    "\t\t\t\tMULTILAYER_EMBER( mlR );\n"
    "\t\t\t}\n"
    "\t\t\tinputs.albedo.xyz = mlAlbedo.xyz;\n"
    "\t\t\tfloat mlGrey = dot( float3( mlSrgbEncode( mlSpecular.x ), mlSrgbEncode( mlSpecular.y ), mlSrgbEncode( mlSpecular.z ) ), float3( 0.2126, 0.7152, 0.0722 ) );\n"
    "\t\t\tinputs.specular.xyz = _float3( mlSrgbDecode( mlGrey ) );\n"
    "\t\t\tinputs.smoothness = mlSrgbDecode( saturate( mlSmooth ) );\n"
    "\t\t\tinputs.normal.xy = saturate( ( mlR.xy * 128.0 + 128.0 ) / 255.0 );\n"
    "\t\t\tfloat mlEm = max( mlEmissive.x, max( mlEmissive.y, mlEmissive.z ) );\n"
    "\t\t\t// the base program adds the emissive twice (the ambient light the albedo multiplies, and its composite):\n"
    "\t\t\t// the mask is divided by 1 + colorscale x color x albedo in the bloom colour's brightest channel\n"
    "\t\t\tfloat3 mlKa = _float3( $colorScale.x ) * $color.xyz * mlAlbedo.xyz;\n"
    "\t\t\tfloat mlKj = ( $bloomColor.x >= max( $bloomColor.y, $bloomColor.z ) ) ? mlKa.x : ( ( $bloomColor.y >= $bloomColor.z ) ? mlKa.y : mlKa.z );\n"
    "\t\t\tmlEm = mlEm / ( 1.0 + max( mlKj, 0.0 ) );\n"
    "\t\t\tfloat mlLm = sqrt( saturate( mlEm ) );\n"
    "\t\t\tinputs.lightmap.x = mlLm;\n"
    "\t\t\tinputs.emissive = _float3( $bloomMaskScale.x * mlLm * mlLm * $colorScale.x ) * $color.xyz * $bloomColor.xyz;\n"
    "\t\t\tinputs.thickness = inputs.lightmap.y;\n"
    "\t\t}\n"
    "\t\t#endtemplate\n"
;
